function nextGreaterElement(a) {
  const result = new Array(a.length).fill(-1);
  const stack = [];
  for (let i = 0; i < a.length; i++) {
    while (stack.length && a[stack[stack.length - 1]] < a[i]) {
      result[stack.pop()] = a[i];
    }
    stack.push(i);
  }
  return result;
}

