using namespace std;
vector<int> nextGreater(vector<int>& a) {
    int n=a.size();
    vector<int> r(n, -1);
    stack<int> s;
    for (int i=0; i<n; i++) {
        while (!s.empty()&&a[s.top()]<a[i]) {
            r[s.top()]=a[i];
            s.pop();
        }
        s.push(i);
    }
    return r;
}
